#3730a3" stroke-width="2"></rect> <rect x="180" y="500" width="60" height="60" fill="#c7d2fe" stroke="#3730a3" stroke-width="2"></rect> <text x="145" y="476" class="rv4-label">1</text> <text x="205" y="476" class="rv4-label">1</text> <text x="145" y="536" class="rv4-label">2</text> <text x="205" y="536" class="rv4-label">3</text> <rect x="112" y="590" width="230" height="28" fill="#ffffff" fill-opacity="0.95" stroke="#d0d0d0"></rect> <text x="128" y="609" class="rv4-small">Valores ubicados en la vista.</text> <!-- PANEL D --> <rect x="480" y="370" width="390" height="300" fill="#f8fbff" stroke="#2f5d8c" stroke-width="2"></rect> <text x="498" y="395" class="rv4-title">D. Segmento diagonal</text> <rect x="520" y="420" width="276" height="192" fill="url(#gridRV4diagAjustado)" stroke="#d9e2ec"></rect> <line x1="580" y1="588" x2="640" y2="588" stroke="#222" stroke-width="3"></line> <line x1="640" y1="588" x2="640" y2="444" stroke="#222" stroke-width="3"></line> <line x1="580" y1="588" x2="640" y2="444" stroke="#c0392b" stroke-width="4"></line> <path d="M640 588 L622 588 L622 570 L640 570" fill="none" stroke="#222" stroke-width="2"></path> <circle cx="580" cy="588" r="5" fill="#2f5d8c"></circle> <circle cx="640" cy="444" r="5" fill="#2f5d8c"></circle> <rect x="585" y="617" width="58" height="24" fill="#ffffff" fill-opacity="0.95" stroke="#d0d0d0"></rect> <text x="599" y="634" class="rv4-small">5 u</text> <rect x="650" y="505" width="62" height="24" fill="#ffffff" fill-opacity="0.95" stroke="#d0d0d0"></rect> <text x="665" y="522" class="rv4-small">12 u</text> </svg></div>
